111	// Look up reliability scores for a list of user IDs in one query.
112	async function getReliabilityMap(userIds: string[]): Promise<Map<string, number>> {
113	  if (userIds.length === 0) return new Map();
114	  const profiles = await db.select({ userId: userProfilesTable.userId, reliabilityScore: userProfilesTable.reliabilityScore })
115	    .from(userProfilesTable)
116	    .where(inArray(userProfilesTable.userId, userIds));
117	  return new Map(profiles.map(p => [p.userId, p.reliabilityScore ?? 100]));
118	}
