124	// GET /games/my — games where I'm creator or participant (game history)
125	router.get("/games/my", requireAuth, async (req, res): Promise<void> => {
126	  const userId = getCurrentUserId(req)!;
127	
128	  // Games where user is a participant (joined) — targeted query
129	  const participantRows = await db
130	    .select({ gameId: gameParticipantsTable.gameId, team: gameParticipantsTable.team })
131	    .from(gameParticipantsTable)
132	    .where(and(eq(gameParticipantsTable.userId, userId), eq(gameParticipantsTable.status, "joined")));
133	  const participantGameIds = participantRows.map(r => r.gameId);
134	  const myTeamMap = new Map(participantRows.map(r => [r.gameId, r.team]));
135	
136	  // Fetch only games where user is creator OR participant — no full table scan
137	  const games = participantGameIds.length > 0
138	    ? await db.select().from(gamesTable)
139	        .where(or(eq(gamesTable.creatorUserId, userId), inArray(gamesTable.id, participantGameIds)))
140	        .orderBy(desc(gamesTable.datetime))
141	    : await db.select().from(gamesTable)
142	        .where(eq(gamesTable.creatorUserId, userId))
143	        .orderBy(desc(gamesTable.datetime));
144	
145	  if (games.length === 0) { res.json([]); return; }
146	
147	  const gameIds = games.map(g => g.id);
148	
149	  // Get participants only for these specific games
150	  const allParticipants = await db
151	    .select()
152	    .from(gameParticipantsTable)
153	    .where(and(inArray(gameParticipantsTable.gameId, gameIds), eq(gameParticipantsTable.status, "joined")));
154	  const participantsByGame = new Map<number, typeof allParticipants>();
155	  for (const p of allParticipants) {
156	    if (!participantsByGame.has(p.gameId)) participantsByGame.set(p.gameId, []);
157	    participantsByGame.get(p.gameId)!.push(p);
158	  }
159	
160	  // Get results only for these specific games
161	  const results = await db.select().from(gameResultsTable)
162	    .where(inArray(gameResultsTable.gameId, gameIds));
163	  const resultByGame = new Map(results.map(r => [r.gameId, r]));
164	
165	  // Get ELO ratings only for the relevant user IDs across these games
166	  const allUserIds = [...new Set(allParticipants.map(p => p.userId))];
167	  const ratings = allUserIds.length > 0
168	    ? await db.select().from(userRatingsTable).where(inArray(userRatingsTable.userId, allUserIds))
169	    : [];
170	  const ratingKey = (uid: string, sport: string) => `${uid}::${sport}`;
171	  const ratingMap = new Map(ratings.map(r => [ratingKey(r.userId, r.sportSlug), r.elo]));
172	
173	  // Fetch booking/court/facility info for games that have a booking
174	  const bookingGameIds = games.filter(g => g.bookingId != null).map(g => g.id);
175	  type BookingRow = {
176	    gameId: number;
177	    bookingId: number;
178	    courtId: number | null;
179	    courtName: string | null;
180	    facilityName: string | null;
181	    facilityCity: string | null;
182	    courtImageUrl: string | null;
183	    date: string | null;
184	    startTime: string | null;
185	    endTime: string | null;
186	    pricePerSlot: number | null;
187	    totalSlots: number | null;
188	  };
189	  const bookingInfoMap = new Map<number, BookingRow>();
190	  if (bookingGameIds.length > 0) {
191	    const bookingRows = await db
192	      .select({
193	        gameId: gamesTable.id,
194	        bookingId: bookingsTable.id,
195	        courtId: courtsTable.id,
196	        courtName: courtsTable.name,
197	        facilityName: facilitiesTable.name,
198	        facilityCity: facilitiesTable.city,
199	        courtImageUrl: courtsTable.imageUrl,
200	        date: bookingsTable.date,
201	        startTime: bookingsTable.startTime,
202	        endTime: bookingsTable.endTime,
203	        pricePerSlot: bookingsTable.pricePerSlot,
204	        totalSlots: bookingsTable.totalSlots,
205	      })
206	      .from(gamesTable)
207	      .innerJoin(bookingsTable, eq(gamesTable.bookingId, bookingsTable.id))
208	      .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
209	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
210	      .where(inArray(gamesTable.id, bookingGameIds));
211	    for (const row of bookingRows) {
212	      bookingInfoMap.set(row.gameId, {
213	        ...row,
214	        pricePerSlot: row.pricePerSlot != null ? Number(row.pricePerSlot) : null,
215	      });
216	    }
217	  }
218	
219	  const out = games.map(g => {
220	    const participants = participantsByGame.get(g.id) ?? [];
221	    const result = resultByGame.get(g.id) ?? null;
222	    const myTeam = myTeamMap.get(g.id) ?? null;
223	    const booking = bookingInfoMap.get(g.id) ?? null;
224	
225	    // Determine win/loss/draw for this user
226	    let myResult: "win" | "loss" | "draw" | null = null;
227	    if (result && result.status === "confirmed" && myTeam) {
228	      const teamWon = result.scoreTeamA > result.scoreTeamB ? "A" :
229	                      result.scoreTeamB > result.scoreTeamA ? "B" : "draw";
230	      if (teamWon === "draw") myResult = "draw";
231	      else myResult = teamWon === myTeam ? "win" : "loss";
232	    }
233	
234	    return {
235	      id: g.id,
236	      sport: g.sport,
237	      city: g.city,
238	      placeName: g.placeName,
239	      description: g.description ?? null,
240	      isPrivate: g.isPrivate,
241	      datetime: formatDateTime(g.datetime),
242	      status: g.status,
243	      matchType: g.matchType,
244	      playersNeeded: g.playersNeeded,
245	      isCreator: g.creatorUserId === userId,
246	      myTeam,
247	      myResult,
248	      bookingId: booking?.bookingId ?? null,
249	      courtId: booking?.courtId ?? null,
250	      courtName: booking?.courtName ?? null,
251	      facilityName: booking?.facilityName ?? null,
252	      facilityCity: booking?.facilityCity ?? null,
253	      courtImageUrl: booking?.courtImageUrl ?? null,
254	      date: booking?.date ?? null,
255	      startTime: booking?.startTime ?? null,
256	      endTime: booking?.endTime ?? null,
257	      pricePerSlot: booking?.pricePerSlot ?? null,
258	      totalSlots: booking?.totalSlots ?? null,
259	      result: result ? {
260	        scoreTeamA: result.scoreTeamA,
261	        scoreTeamB: result.scoreTeamB,
262	        status: result.status,
263	      } : null,
264	      participants: participants.map(p => ({
265	        userId: p.userId,
266	        userName: p.userName,
267	        team: p.team,
268	        elo: ratingMap.get(ratingKey(p.userId, g.sport)) ?? 1200,
269	      })),
270	    };
271	  });
272	
273	  res.json(out);
274	});
