276	// GET /games — list all open upcoming games with filters
277	router.get("/games", async (req, res): Promise<void> => {
278	  const userId = getCurrentUserId(req);
279	
280	  let rows = await db
281	    .select()
282	    .from(gamesTable)
283	    .where(and(
284	      eq(gamesTable.status, "open"),
285	      eq(gamesTable.isPrivate, false),
286	    ))
287	    .orderBy(gamesTable.datetime);
288	
289	  if (req.query.sport) rows = rows.filter(r => r.sport === req.query.sport);
290	  if (req.query.city) rows = rows.filter(r => r.city.toLowerCase() === String(req.query.city).toLowerCase());
291	  if (req.query.skillLevel) rows = rows.filter(r => r.skillLevel === req.query.skillLevel || r.skillLevel === "any");
292	
293	  // Filter out past games
294	  const now = new Date();
295	  rows = rows.filter(r => new Date(r.datetime) >= now);
296	
297	  // Attach participant counts
298	  const counts = await db
299	    .select({ gameId: gameParticipantsTable.gameId, count: sql<number>`count(*)` })
300	    .from(gameParticipantsTable)
301	    .where(eq(gameParticipantsTable.status, "joined"))
302	    .groupBy(gameParticipantsTable.gameId);
303	  const countMap = new Map(counts.map(c => [c.gameId, Number(c.count)]));
304	
305	  let joinedSet = new Set<number>();
306	  if (userId) {
307	    const mine = await db.select({ gameId: gameParticipantsTable.gameId }).from(gameParticipantsTable)
308	      .where(and(eq(gameParticipantsTable.userId, userId), eq(gameParticipantsTable.status, "joined")));
309	    joinedSet = new Set(mine.map(m => m.gameId));
310	  }
311	
312	  res.json(rows.map(g => formatGame(g, countMap.get(g.id) ?? 0, joinedSet.has(g.id), !!(userId && userId === g.creatorUserId))));
313	});
