315	// GET /games/:id — detail (public, but shares private games via token)
316	router.get("/games/:id", async (req, res): Promise<void> => {
317	  const id = parseInt(String(req.params.id), 10);
318	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
319	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
320	  if (!g) { res.status(404).json({ error: "Game not found" }); return; }
321	
322	  // Private games require the invite token
323	  if (g.isPrivate && g.inviteToken !== req.query.token) {
324	    const userId = getCurrentUserId(req);
325	    if (!userId || (userId !== g.creatorUserId)) {
326	      res.status(403).json({ error: "This game is private" }); return;
327	    }
328	  }
329	
330	  const userId = getCurrentUserId(req);
331	  const isCreator = userId === g.creatorUserId;
332	
333	  const participants = await db.select().from(gameParticipantsTable)
334	    .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.status, "joined")))
335	    .orderBy(gameParticipantsTable.joinedAt);
336	
337	  const isJoined = userId ? participants.some(p => p.userId === userId) : false;
338	
339	  // Check if current user has a pending join request
340	  let isPending = false;
341	  if (userId && !isJoined) {
342	    const [myRow] = await db.select().from(gameParticipantsTable)
343	      .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.userId, userId), eq(gameParticipantsTable.status, "pending")));
344	    isPending = !!myRow;
345	  }
346	
347	  // For creator: fetch pending join requests
348	  let pendingParticipants: typeof participants = [];
349	  if (isCreator) {
350	    pendingParticipants = await db.select().from(gameParticipantsTable)
351	      .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.status, "pending")))
352	      .orderBy(gameParticipantsTable.joinedAt);
353	  }
354	
355	  // Fetch ELO ratings + reliability scores for participants
356	  const participantRatings = await Promise.all(
357	    participants.map(p => db.select().from(userRatingsTable)
358	      .where(and(eq(userRatingsTable.userId, p.userId), eq(userRatingsTable.sportSlug, g.sport)))
359	      .limit(1).then(rows => ({ userId: p.userId, elo: rows[0]?.elo ?? 1200 })))
360	  );
361	  const ratingMap = new Map(participantRatings.map(r => [r.userId, r.elo]));
362	  const reliabilityMap = await getReliabilityMap(participants.map(p => p.userId));
363	
364	  const gameData = formatGame(g, participants.length, isJoined, isCreator);
365	  // Expose internal user IDs only to authenticated game participants, not public visitors
366	  const isAuthenticatedParticipant = isJoined || isCreator;
367	  res.json({
368	    ...gameData,
369	    ...(isCreator && g.inviteToken ? { inviteToken: g.inviteToken } : {}),
370	    ...(isAuthenticatedParticipant ? { creatorUserId: g.creatorUserId } : {}),
371	    isPending,
372	    participants: participants.map(p => ({
373	      ...(isAuthenticatedParticipant ? formatParticipantWithId(p) : formatParticipant(p)),
374	      elo: ratingMap.get(p.userId) ?? 1200,
375	      reliabilityScore: reliabilityMap.get(p.userId) ?? 100,
376	      isOrganizer: p.userId === g.creatorUserId,
377	    })),
378	    pendingParticipants: pendingParticipants.map(p => formatParticipantWithId(p)),
379	  });
380	});
