382	// POST /games — create
383	router.post("/games", requireAuth, async (req, res): Promise<void> => {
384	  const userId = getCurrentUserId(req)!;
385	  const {
386	    creatorName, creatorEmail, sport, city, placeName, facilityId, courtId,
387	    playersNeeded, skillLevel, datetime, durationMinutes, description, isPrivate,
388	    matchType, requiresApproval, teamCount, minSkillLevel, maxSkillLevel,
389	  } = req.body ?? {};
390	
391	  if (!creatorName || !sport || !city || !datetime) {
392	    res.status(400).json({ error: "creatorName, sport, city, datetime required" }); return;
393	  }
394	
395	  const parsedMinElo = minSkillLevel != null && minSkillLevel !== "" ? parseFloat(String(minSkillLevel)) : null;
396	  const parsedMaxElo = maxSkillLevel != null && maxSkillLevel !== "" ? parseFloat(String(maxSkillLevel)) : null;
397	
398	  const inviteToken = isPrivate ? crypto.randomBytes(16).toString("hex") : null;
399	
400	  const [game] = await db.insert(gamesTable).values({
401	    creatorUserId: userId,
402	    creatorName,
403	    creatorEmail: creatorEmail ?? null,
404	    sport,
405	    city,
406	    placeName: placeName ?? null,
407	    facilityId: facilityId ?? null,
408	    courtId: courtId ?? null,
409	    playersNeeded: playersNeeded ?? 4,
410	    skillLevel: skillLevel ?? "any",
411	    minSkillLevel: Number.isFinite(parsedMinElo) ? parsedMinElo : null,
412	    maxSkillLevel: Number.isFinite(parsedMaxElo) ? parsedMaxElo : null,
413	    datetime,
414	    durationMinutes: durationMinutes ?? 60,
415	    description: description ?? null,
416	    isPrivate: !!isPrivate,
417	    visibility: isPrivate ? "private" : "public",
418	    requiresApproval: !!requiresApproval,
419	    teamCount: teamCount ? Math.max(2, Math.min(6, Number(teamCount))) : 2,
420	    inviteToken,
421	    status: "open",
422	    matchType: matchType === "rated" ? "rated" : "casual",
423	  }).returning();
424	
425	  // Creator auto-joins
426	  await db.insert(gameParticipantsTable).values({
427	    gameId: game.id,
428	    userId,
429	    userName: creatorName,
430	    userEmail: creatorEmail ?? null,
431	    status: "joined",
432	  });
433	
434	  const created = formatGame(game, 1, true, true);
435	  res.status(201).json(game.inviteToken ? { ...created, inviteToken: game.inviteToken } : created);
436	});
