438	// PUT /games/:id — creator only
439	router.put("/games/:id", requireAuth, async (req, res): Promise<void> => {
440	  const id = parseInt(String(req.params.id), 10);
441	  const userId = getCurrentUserId(req)!;
442	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
443	  if (!g) { res.status(404).json({ error: "Not found" }); return; }
444	  if (g.creatorUserId !== userId) { res.status(403).json({ error: "Forbidden" }); return; }
445	
446	  const {
447	    sport, city, placeName, playersNeeded, skillLevel, datetime, durationMinutes,
448	    description, status,
449	  } = req.body ?? {};
450	
451	  const [updated] = await db.update(gamesTable).set({
452	    ...(sport !== undefined && { sport }),
453	    ...(city !== undefined && { city }),
454	    ...(placeName !== undefined && { placeName: placeName ?? null }),
455	    ...(playersNeeded !== undefined && { playersNeeded }),
456	    ...(skillLevel !== undefined && { skillLevel }),
457	    ...(datetime !== undefined && { datetime }),
458	    ...(durationMinutes !== undefined && { durationMinutes }),
459	    ...(description !== undefined && { description: description ?? null }),
460	    ...(status !== undefined && { status }),
461	  }).where(eq(gamesTable.id, id)).returning();
462	
463	  res.json(formatGame(updated, 0, false, true));
464	});
