466	// DELETE /games/:id — creator only
467	// GET /games/:id/refund-preview — host-cancellation refund preview (mirrors bookings preview).
468	// Returns canCancel:false with reason when the game has no linked paid booking — the host can
469	// still delete the game in that case (no money is at stake), the dialog just shows a plain warning.
470	router.get("/games/:id/refund-preview", requireAuth, async (req, res): Promise<void> => {
471	  const id = parseInt(String(req.params.id), 10);
472	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
473	  const userId = getCurrentUserId(req)!;
474	
475	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
476	  if (!g) { res.status(404).json({ error: "Not found" }); return; }
477	  if (g.creatorUserId !== userId) { res.status(403).json({ error: "Forbidden" }); return; }
478	
479	  if (!g.bookingId) {
480	    res.json({
481	      gameId: g.id,
482	      bookingId: null,
483	      hasBooking: false,
484	      totalPrice: 0,
485	      hoursBeforeStart: 0,
486	      refundPercent: 0,
487	      refundAmount: 0,
488	      refundable: false,
489	      canCancel: true,
490	    });
491	    return;
492	  }
493	
494	  const [booking] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, g.bookingId));
495	  if (!booking) {
496	    res.json({
497	      gameId: g.id,
498	      bookingId: g.bookingId,
499	      hasBooking: false,
500	      totalPrice: 0,
501	      hoursBeforeStart: 0,
502	      refundPercent: 0,
503	      refundAmount: 0,
504	      refundable: false,
505	      canCancel: true,
506	    });
507	    return;
508	  }
509	
510	  const totalPriceEur = Number(booking.totalPrice);
511	  const hours = hoursBeforeStart(booking.date, booking.startTime);
512	  const tier = computeRefund(totalPriceEur, hours);
513	  const canCancel = booking.status !== "cancelled" && hours > 0;
514	  let reason: string | undefined;
515	  if (booking.status === "cancelled") reason = "Rezervacija jau atšaukta.";
516	  else if (hours <= 0) reason = "Žaidimas jau prasidėjo arba pasibaigė.";
517	
518	  res.json({
519	    gameId: g.id,
520	    bookingId: booking.id,
521	    hasBooking: true,
522	    totalPrice: totalPriceEur,
523	    hoursBeforeStart: Math.round(hours * 10) / 10,
524	    refundPercent: tier.refundPercent,
525	    refundAmount: tier.refundAmount,
526	    refundable: tier.refundable,
527	    canCancel,
528	    ...(reason ? { reason } : {}),
529	  });
530	});
