532	router.delete("/games/:id", requireAuth, async (req, res): Promise<void> => {
533	  const id = parseInt(String(req.params.id), 10);
534	  const userId = getCurrentUserId(req)!;
535	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
536	  if (!g) { res.status(404).json({ error: "Not found" }); return; }
537	  if (g.creatorUserId !== userId) { res.status(403).json({ error: "Forbidden" }); return; }
538	
539	  // ─── Single-owner cancellation claim ─────────────────────────────────────────
540	  // CAS the game into 'cancelling' so that concurrent DELETEs are rejected with 409.
541	  // Without this, a second request could race past the booking-CAS (which would
542	  // already be claimed) and delete the game while the first request's Stripe call
543	  // is still in flight, producing "game deleted but booking still confirmed and
544	  // no refund issued" if Stripe then fails and the first request rolls booking back.
545	  const originalStatus = g.status;
546	  const claimGame = await db
547	    .update(gamesTable)
548	    .set({ status: "cancelling" })
549	    .where(and(eq(gamesTable.id, id), ne(gamesTable.status, "cancelling")))
550	    .returning();
551	  if (claimGame.length === 0) {
552	    res.status(409).json({ error: "Atšaukimas jau vykdomas. Bandykite po akimirkos." });
553	    return;
554	  }
555	
556	  // ─── If a paid Korts.lt booking is linked, mirror the standard booking-cancel + refund flow ──
557	  let refundedAmount = 0;
558	  let refundPercent = 0;
559	  if (g.bookingId) {
560	    const [booking] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, g.bookingId));
561	    if (booking && booking.status !== "cancelled") {
562	      const totalPriceEur = Number(booking.totalPrice);
563	      const hours = hoursBeforeStart(booking.date, booking.startTime);
564	      if (hours <= 0) {
565	        res.status(400).json({ error: "Žaidimas jau prasidėjo arba pasibaigė", code: "CANCEL_TOO_LATE" });
566	        return;
567	      }
568	      const tier = computeRefund(totalPriceEur, hours);
569	
570	      // CAS on booking status to prevent double-refund if the host clicks twice or the
571	      // sweeper races us on a still-pending booking.
572	      const claimed = await db
573	        .update(bookingsTable)
574	        .set({ status: "cancelled" })
575	        .where(and(eq(bookingsTable.id, booking.id), ne(bookingsTable.status, "cancelled")))
576	        .returning();
577	
578	      if (claimed.length > 0) {
579	        let stripeRefundId: string | null = null;
580	        if (
581	          tier.refundable &&
582	          tier.refundAmount > 0 &&
583	          booking.stripePaymentIntentId &&
584	          !booking.stripePaymentIntentId.startsWith("mock_")
585	        ) {
586	          try {
587	            const stripe = await getUncachableStripeClient();
588	            const refund = await stripe.refunds.create(
589	              {
590	                payment_intent: booking.stripePaymentIntentId,
591	                amount: Math.round(tier.refundAmount * 100),
592	                reason: "requested_by_customer",
593	              },
594	              { idempotencyKey: `cancel-game-${g.id}` },
595	            );
596	            stripeRefundId = refund.id;
597	            logger.info(
598	              { gameId: g.id, bookingId: booking.id, refundId: refund.id, amount: tier.refundAmount },
599	              "Stripe refund issued for host-cancelled game",
600	            );
601	          } catch (err) {
602	            logger.error({ err, gameId: g.id, bookingId: booking.id }, "Stripe refund failed");
603	            // Roll back BOTH booking and game status so the host can retry.
604	            // Without restoring game.status, the next attempt would 409 forever.
605	            await db
606	              .update(bookingsTable)
607	              .set({ status: booking.status })
608	              .where(eq(bookingsTable.id, booking.id));
609	            await db
610	              .update(gamesTable)
611	              .set({ status: originalStatus })
612	              .where(eq(gamesTable.id, g.id));
613	            res.status(502).json({ error: "Nepavyko grąžinti pinigų. Bandykite dar kartą." });
614	            return;
615	          }
616	        }
617	
618	        await db
619	          .update(bookingsTable)
620	          .set({ refundAmount: String(tier.refundAmount), stripeRefundId })
621	          .where(eq(bookingsTable.id, booking.id));
622	
623	        refundedAmount = tier.refundAmount;
624	        refundPercent = tier.refundPercent;
625	      }
626	    }
627	  }
628	
629	  // Collect all participants before deleting (except creator) so we can notify them.
630	  const participants = await db
631	    .select()
632	    .from(gameParticipantsTable)
633	    .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.status, "joined")));
634	
635	  // bookingId on games has ON DELETE SET NULL, so the booking row (now 'cancelled')
636	  // survives for refund history; participants/results/chat cascade-delete with the game.
637	  await db.delete(gamesTable).where(eq(gamesTable.id, id));
638	
639	  // Notify all joined participants that the host cancelled.
640	  const sportLabel = g.sport.replace(/_/g, " ");
641	  const gameDate = new Date(g.datetime).toLocaleDateString("lt-LT");
642	  for (const p of participants) {
643	    if (p.userId && p.userId !== userId) {
644	      await sendNotification(
645	        p.userId,
646	        "game_cancelled",
647	        "Žaidimas atšauktas",
648	        `${sportLabel} žaidimas ${gameDate} (${g.city}) buvo atšauktas organizatoriaus.`,
649	        "/matches",
650	      );
651	    }
652	  }
653	
654	  res.json({ ok: true, refundAmount: refundedAmount, refundPercent });
655	});
