958	router.post("/games/:id/result", requireAuth, async (req, res): Promise<void> => {
959	  const id = parseInt(String(req.params.id), 10);
960	  const userId = getCurrentUserId(req)!;
961	
962	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
963	  if (!g) { res.status(404).json({ error: "Game not found" }); return; }
964	  if (g.creatorUserId !== userId) { res.status(403).json({ error: "Only the game creator can report results" }); return; }
965	  if (g.status !== "open" && g.status !== "full") { res.status(400).json({ error: "Game is not in a reportable state" }); return; }
966	
967	  // Time gate: result can only be reported after the game has ended
968	  const endsAtMs = new Date(g.datetime).getTime() + (g.durationMinutes ?? 0) * 60_000;
969	  if (Date.now() < endsAtMs) {
970	    res.status(400).json({ error: "Žaidimas dar nepasibaigė — rezultatą galima paskelbti tik po žaidimo pabaigos." });
971	    return;
972	  }
973	
974	  // Accept either a structured `score` (preferred, sport-typed) or legacy scoreTeamA/scoreTeamB.
975	  const { scoreTeamA, scoreTeamB, score } = req.body ?? {};
976	  const hasStructured = score && typeof score === "object" && (score.type === "SET_BASED" || score.type === "POINT_BASED");
977	
978	  let teamAScore: number;
979	  let teamBScore: number;
980	  let structuredScore: SportScore | null = null;
981	
982	  if (hasStructured) {
983	    const cfg = getSportConfig(g.sport);
984	    const errs = validateScore(score as SportScore, cfg);
985	    if (errs.length > 0) { res.status(400).json({ error: errs[0].message }); return; }
986	    structuredScore = score as SportScore;
987	    // Casual games drive ELO — require an unambiguous winner (no ties).
988	    const side = deriveWinner(structuredScore, cfg);
989	    if (!side) {
990	      res.status(400).json({ error: "Lygiosios negalimos – nustatykite nugalėtoją." }); return;
991	    }
992	    if (cfg.scoringType === "SET_BASED") {
993	      const sets = setsWonFromScore(structuredScore);
994	      teamAScore = sets.a;
995	      teamBScore = sets.b;
996	    } else {
997	      const pts = pointsWonFromScore(structuredScore);
998	      teamAScore = pts.a;
999	      teamBScore = pts.b;
