1624	// ─── Exported helper: apply ELO for a confirmed result (used by /verify and the auto-confirm cron) ──
1625	export async function applyResultElo(gameResultId: number): Promise<void> {
1626	  const [result] = await db.select().from(gameResultsTable).where(eq(gameResultsTable.id, gameResultId));
1627	  if (!result) return;
1628	  if (result.status === "confirmed") return; // idempotent
1629	
1630	  // Only the FIRST caller flips status (race between /verify-confirm and cron).
1631	  const flipped = await db
1632	    .update(gameResultsTable)
1633	    .set({ status: "confirmed" })
1634	    .where(and(eq(gameResultsTable.id, gameResultId), eq(gameResultsTable.status, "pending_verification")))
1635	    .returning();
1636	  if (flipped.length === 0) return; // somebody else already promoted
1637	
1638	  await db.update(gamesTable).set({ status: "completed" }).where(eq(gamesTable.id, result.gameId));
1639	
1640	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, result.gameId));
1641	  if (!g || g.matchType !== "rated") return;
1642	
1643	  const participants = await db.select().from(gameParticipantsTable)
1644	    .where(and(eq(gameParticipantsTable.gameId, g.id), eq(gameParticipantsTable.status, "joined")));
1645	  const teamAPlayers = participants.filter(p => p.team === "A");
1646	  const teamBPlayers = participants.filter(p => p.team === "B");
1647	  const unassigned = participants.filter(p => !p.team);
1648	  const effectiveTeamA = teamAPlayers.length ? teamAPlayers : unassigned.slice(0, Math.ceil(unassigned.length / 2));
1649	  const effectiveTeamB = teamBPlayers.length ? teamBPlayers : unassigned.slice(Math.ceil(unassigned.length / 2));
1650	
1651	  const teamAWithElo = await Promise.all(effectiveTeamA.map(async p => ({ userId: p.userId, elo: (await getOrCreateRating(p.userId, g.sport)).elo })));
1652	  const teamBWithElo = await Promise.all(effectiveTeamB.map(async p => ({ userId: p.userId, elo: (await getOrCreateRating(p.userId, g.sport)).elo })));
1653	
1654	  const winner: "A" | "B" | "draw" =
1655	    result.scoreTeamA > result.scoreTeamB ? "A" :
1656	    result.scoreTeamB > result.scoreTeamA ? "B" : "draw";
1657	  const changes = calculateTeamElo(teamAWithElo, teamBWithElo, winner);
1658	  const isDraw = winner === "draw";
1659	
1660	  for (const change of changes) {
1661	    const isOnTeamA = !!teamAWithElo.find(p => p.userId === change.userId);
1662	    const isWinner = isDraw ? false : (isOnTeamA ? winner === "A" : winner === "B");
1663	    const winsAdd = isDraw ? 0 : (isWinner ? 1 : 0);
1664	    const lossesAdd = isDraw ? 0 : (!isWinner ? 1 : 0);
1665	    const drawsAdd = isDraw ? 1 : 0;
1666	
1667	    await db.update(userRatingsTable)
1668	      .set({
1669	        elo: change.newElo,
1670	        wins: sql`${userRatingsTable.wins} + ${winsAdd}`,
1671	        losses: sql`${userRatingsTable.losses} + ${lossesAdd}`,
1672	        draws: sql`${userRatingsTable.draws} + ${drawsAdd}`,
1673	        updatedAt: new Date(),
1674	      })
1675	      .where(and(eq(userRatingsTable.userId, change.userId), eq(userRatingsTable.sportSlug, g.sport)));
1676	
1677	    await db.insert(eloHistoryTable).values({
1678	      userId: change.userId,
1679	      sportSlug: g.sport,
1680	      elo: change.newElo,
1681	      delta: change.delta,
1682	      gameId: g.id,
1683	    });
1684	
1685	    const sign = change.delta > 0 ? "+" : "";
1686	    await sendNotification(
1687	      change.userId,
1688	      "elo_update",
1689	      `ELO pasikeitė: ${sign}${change.delta}`,
1690	      `Žaidimas (${g.sport}) baigtas. Reitingas: ${change.oldElo} → ${change.newElo} (${sign}${change.delta}).`,
1691	      `/matches/${g.id}`,
1692	    );
1693	  }
1694	}
