1696	// ─── Sweepers (called from cron) ──
1697	export async function sweepStalePendingGames(): Promise<number> {
1698	  // Find games stuck in pending_payment for > 15 min (Stripe abandoned/expired).
1699	  const stale = await db.select({ id: gamesTable.id, bookingId: gamesTable.bookingId })
1700	    .from(gamesTable)
1701	    .where(and(
1702	      eq(gamesTable.status, "pending_payment"),
1703	      sql`${gamesTable.createdAt} < NOW() - INTERVAL '15 minutes'`,
1704	    ));
1705	  if (stale.length === 0) return 0;
1706	
1707	  for (const row of stale) {
1708	    if (row.bookingId) {
1709	      await db.update(bookingsTable)
1710	        .set({ status: "cancelled" })
1711	        .where(and(eq(bookingsTable.id, row.bookingId), ne(bookingsTable.status, "confirmed")));
1712	    }
1713	    await db.delete(gamesTable).where(and(eq(gamesTable.id, row.id), eq(gamesTable.status, "pending_payment")));
1714	  }
1715	  return stale.length;
1716	}
