1718	export async function sweepAutoConfirmResults(): Promise<number> {
1719	  const due = await db.select({ id: gameResultsTable.id })
1720	    .from(gameResultsTable)
1721	    .where(and(
1722	      eq(gameResultsTable.status, "pending_verification"),
1723	      lt(gameResultsTable.autoConfirmAt, new Date()),
